                      </label>
                    </div>
                    <div className="setting-field checkbox-field">
                      <label>
                        <input 
                          type="checkbox" 
                          checked={notificationSettings.sellerPayoutAlerts} 
                          onChange={(e) => setNotificationSettings({ ...notificationSettings, sellerPayoutAlerts: e.target.checked })} 
                        />
                        Seller Payout & Commission Notifications
                      </label>
                    </div>
                    <div className="setting-field checkbox-field">
                      <label>
                        <input 
                          type="checkbox" 
                          checked={notificationSettings.systemLogsAlerts} 
                          onChange={(e) => setNotificationSettings({ ...notificationSettings, systemLogsAlerts: e.target.checked })} 
                        />
                        Critical Audit Log Alerts
                      </label>
                    </div>
                  </div>
                  <div className="settings-actions">
                    <button type="submit" className="btn-save-settings">Save Notification Preferences</button>
                  </div>
                </form>
              )}
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="admin-dashboard-container">
      {/* Sidebar Navigation */}
      <aside className="admin-sidebar">
        <div className="sidebar-brand">
          <h2>HEXCART</h2>
          <span className="brand-badge">Admin Suite</span>
        </div>
        <nav className="sidebar-nav">
          <button className={activeTab === 'overview' ? 'active' : ''} onClick={() => setActiveTab('overview')}>Overview</button>
          <button className={activeTab === 'user-info' ? 'active' : ''} onClick={() => setActiveTab('user-info')}>User Directory</button>
          <button className={activeTab === 'seller-info' ? 'active' : ''} onClick={() => setActiveTab('seller-info')}>Seller Directory</button>
          <button className={activeTab === 'users' ? 'active' : ''} onClick={() => setActiveTab('users')}>Buyer Controls</button>
          <button className={activeTab === 'sellers' ? 'active' : ''} onClick={() => setActiveTab('sellers')}>Seller Controls</button>
          <button className={activeTab === 'logs' ? 'active' : ''} onClick={() => setActiveTab('logs')}>Audit Logs</button>
          <button className={activeTab === 'settings' ? 'active' : ''} onClick={() => setActiveTab('settings')}>Settings</button>
        </nav>
      </aside>

      {/* Main Content Viewport */}
      <main className="admin-main-content">
        <header className="dashboard-topbar">
          <div className="search-bar-container">
            <input 
              type="text" 
              placeholder="Search users, sellers, or email..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="user-profile-widget">
            <Link to="/" className="btn-home-link">Back to Store</Link>
          </div>
        </header>

        {renderContent()}
      </main>

      {/* User/Seller Detail Modal */}
      {detailModalItem && (
        <div className="modal-overlay" onClick={() => setDetailModalItem(null)}>
          <div className="modal-card" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>{detailModalItem.role === 'Seller' ? detailModalItem.storeName : detailModalItem.name}</h3>
              <button className="modal-close-btn" onClick={() => setDetailModalItem(null)}>&times;</button>
            </div>
            <div className="modal-body">
              <p><strong>ID:</strong> {detailModalItem.id}</p>
              <p><strong>Name:</strong> {detailModalItem.name}</p>
              <p><strong>Email:</strong> {detailModalItem.email}</p>
              <p><strong>Phone:</strong> {detailModalItem.phone || 'N/A'}</p>
              <p><strong>Status:</strong> {detailModalItem.status}</p>
              {detailModalItem.role === 'Seller' ? (
                <>
                  <p><strong>Category:</strong> {detailModalItem.category}</p>
                  <p><strong>Total Revenue:</strong> {detailModalItem.totalRevenue}</p>
                </>
              ) : (
                <>
                  <p><strong>Tier:</strong> {detailModalItem.tier}</p>
                  <p><strong>Total Spent:</strong> {detailModalItem.totalSpent}</p>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
